import React, { useState } from 'react';
import { Attach, Button } from '@salutejs/sdds-finai';
export function App() {
    const [result, setResult] = useState('');
    const handleSubmit = (e) => {
        e.preventDefault();
        const files = new FormData(e.target).getAll('avatar');
        setResult(files.map((f) => f.name).join(', ') || 'Файлы не выбраны');
    };
    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            <form
                onSubmit={handleSubmit}
                style={{ display: 'flex', gap: '16px', alignItems: 'flex-start' }}
            >
                <Attach name="avatar" />
                <Button type="submit">Отправить</Button>
            </form>
            {result && <span>Отправлены: {result}</span>}
        </div>
    );
}

import React from 'react';
import { useForm, Controller } from 'react-hook-form';
import { Attach, Button } from '@salutejs/sdds-finai';
export function App() {
    const { control, handleSubmit } = useForm();
    const onSubmit = (data) => console.log('Файлы:', data.files);
    return (
        <form onSubmit={handleSubmit(onSubmit)}>
            <Controller
                name="files"
                control={control}
                defaultValue={[]}
                render={(props) => {
                    const { value, onChange: onRhfChange } = props.field;
                    return (
                        <Attach
                            files={value}
                            onChange={(e) => onRhfChange(Array.from(e.target.files || []))}
                            onClear={(fileInfo) => onRhfChange(value.filter((f) => f !== fileInfo.file))}
                        />
                    );
                }}
            />
            <Button type="submit">Отправить</Button>
        </form>
    );
}

import React, { useState } from 'react';
import { Attach, Button, InformationWrapper, outlineSolidPrimary } from '@salutejs/sdds-finai';
function App() {
    const [isLoading, setIsLoading] = useState(false);
    const [attachedFiles, setAttachedFiles] = useState([]);
    const handleAttachFile = (e) => {
        setAttachedFiles((prevAttachedFiles) => [
            ...prevAttachedFiles,
            {
                fileData: e.target.files[0],
                id: e.target.id,
            },
        ]);
    };
    const handleAttachClear = (id) => {
        setAttachedFiles(attachedFiles.filter((file) => file.id !== id));
    };
    const handleSubmit = (e) => {
        e.preventDefault();
        setIsLoading(true);
        const formData = new FormData(e.target);
        console.log('formData', Object.fromEntries(formData));
        setTimeout(() => {
            setAttachedFiles([]);
            setIsLoading(false);
        }, 2000);
    };
    return (
        <>
            {!isLoading && (
                <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '30px', padding: '16px 18px', border: `1px dashed ${outlineSolidPrimary}` }}>
                    <InformationWrapper labelHtmlFor="example-id-attach-1" label="Label" hasRequiredIndicator leftHelper="Caption" titleCaption="Title Caption">
                        <Attach
                            id="example-id-attach-1"
                            name="attach-1"
                            text="Upload avatar"
                            onChange={handleAttachFile}
                            onClear={() => handleAttachClear('1')}
                            view="accent"
                        />
                    </InformationWrapper>
                    <InformationWrapper
                        labelHtmlFor="example-id-attach-2"
                        label="Label"
                        leftHelper="Caption"
                        titleCaption="Title Caption"
                        hintText="Example hint text"
                    >
                        <Attach
                            id="example-id-attach-2"
                            name="attach-2"
                            text="Upload config"
                            onChange={handleAttachFile}
                            onClear={() => handleAttachClear('2')}
                            view="accent"
                        />
                    </InformationWrapper>
                    <Button style={{ alignSelf: 'end' }} type="submit">Submit</Button>
                </form>
            )}
            <div style={{ display: 'flex', flexDirection: 'column', padding: '1rem', margin: '16px 0 0 0', border: '1px dashed gray' }}>
                <span>
                    {isLoading ? 'Форма отправляется' : 'Прикрепленные к форме файлы:'}
                </span>
                {!isLoading && attachedFiles.length > 0 && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                        {attachedFiles.map((file) => (
                            <div>{file.fileData.name}</div>
                        ))}
                    </div>
                )}
            </div>
        </>
    );
}
